<script lang="ts">
 import { invalidateAll } from '$app/navigation';import { saveDraft } from '$lib/offline';
 let {model,t,tenantId,userId,role}:{model:Record<string,any[]>;t:(key:string)=>string;tenantId:string;userId:string;role:string}=$props();let message=$state(''),busy=$state(false);
 async function update(task:Record<string,any>,checklist:any[],status=task.status){if(busy)return;busy=true;const command={type:'task_update',task_id:task.id,expected_version:task.version,checklist,status};try{if(!navigator.onLine){await saveDraft(tenantId,command);message=t('draftSaved');return;}const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify(command)});const result=await res.json();message=res.ok?t('saved'):result.message==='VERSION_CONFLICT'?t('conflict'):result.message;if(res.ok)await invalidateAll();}finally{busy=false;}}
</script>
<section class="card"><h2>{t('tasks')}</h2>{#each model.tasks.filter(task=>task.status!=='done') as task}{@const editable=['owner','oenologist','office'].includes(role)||task.assignee_id===userId||task.created_by===userId}<article><h3>{task.title}</h3><p>{task.description}</p><small>{task.due_at?new Date(task.due_at).toLocaleString():''} · {t(task.status)}</small>{#each task.checklist??[] as item,index}<label><input type="checkbox" checked={item.done} disabled={!editable||busy} onchange={(e)=>update(task,task.checklist.map((old:any,i:number)=>i===index?{...old,done:e.currentTarget.checked}:old))} />{item.label}</label>{/each}{#if editable}<button disabled={busy} onclick={()=>update(task,task.checklist,'done')}>{t('done')}</button>{/if}</article>{/each}<p role="status">{message}</p></section>
<style>article{padding:16px 0;border-top:1px solid #e3e8de}article p,small{color:#74816d;font-size:12px}label{display:flex!important;align-items:center;margin:10px 0}button{margin-top:12px;padding:7px 14px!important;font-size:11px!important}</style>
